announcement_revisions_tenant_select.using:
(
    (
      NULLIF(current_setting('app.org_id', true), '') IS NOT NULL
      AND (
        scope = 'site'
        OR org_id = NULLIF(current_setting('app.org_id', true), '')::uuid
      )
    )
    OR (
      current_setting('app.site_admin', true) = '1'
      AND scope = 'site'
    )
  )

